local function first(spawns)
 for map,xy in pairs(spawns or {})do if xy[1]and xy[2]then return {mapID=map,x=xy[1]/100,y=xy[2]/100}end end
end
for _,kind in ipairs({'npcs','objects'})do
 local target=kind=='npcs'and HP.npcData or HP.objectData;local index=kind=='npcs'and 5 or 2
 for id,row in pairs(db[kind])do if not target[id]then target[id]={name=row[1],dingCoords=row[index],location=first(row[index]),minLevel=kind=='npcs'and row[2]or nil,maxLevel=kind=='npcs'and row[3]or nil}end end
end
for id,row in pairs(db.items)do if not HP.itemData[id]then HP.itemData[id]={name=row[1],mobs=row[2],objects=row[3],vendors=row[4]}end end
for id,q in pairs(additions)do
 if not HP.questData[id]then
  local start=q.start and HP.npcData[q.start]or q.startObject and HP.objectData[q.startObject]
  local finish=q.finish and HP.npcData[q.finish]or q.finishObject and HP.objectData[q.finishObject]
  q.startLocation=start and start.location;q.finishLocation=finish and finish.location
  q.navigationPending=q.questieAvailabilityPending or not(q.startLocation or q.startItem)
  HP.questData[id]=q
  for _,zone in pairs(HP.zoneCatalog or {})do if zone.areaID==q.zoneID or zone.zoneID==q.zoneID then q.zone=zone.name; zone.questIDs=zone.questIDs or {};zone.questIDs[#zone.questIDs+1]=id end end
 end
end
